<script setup>import{Link,usePage}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';import ProductCard from'../../Components/ProductCard.vue';import SeoHead from'../../Components/SeoHead.vue';defineProps({heroSlides:Array,productReels:Array,featuredProducts:Array,productCategories:Array,serviceCategories:Array,brands:Array});</script><template><AppLayout><SeoHead title="Prinx Electronics" description="Shop electronics and book professional technical services from Prinx Electronics in Tanzania."/><section class="bg-slate-950 text-white"><div class="container-shell grid min-h-[390px] items-center gap-8 py-12 md:grid-cols-2"><div><p class="section-kicker text-prinx-400">Electronics · Services · Support</p><h1 class="mt-3 text-4xl font-black tracking-tight sm:text-5xl">Technology that works for you.</h1><p class="mt-4 max-w-xl text-slate-300">Shop reliable electronics, accessories and professional technical services with clear product information and dependable support.</p><div class="mt-7 flex gap-3"><Link href="/shop" class="btn-primary">Shop products</Link><Link href="/services" class="btn-light">Explore services</Link></div></div><div v-if="heroSlides?.length" class="card overflow-hidden bg-white text-slate-900"><img :src="heroSlides[0].item.image_url" :alt="heroSlides[0].item.name" class="aspect-[4/3] w-full object-cover"><div class="p-5"><p class="text-xs font-black uppercase text-prinx-600">{{heroSlides[0].eyebrow||'Featured'}}</p><h2 class="mt-1 text-2xl font-black">{{heroSlides[0].headline||heroSlides[0].item.name}}</h2><p class="mt-2 text-sm text-slate-500">{{heroSlides[0].description||heroSlides[0].item.short_description}}</p></div></div></div></section><section class="container-shell py-10"><div class="flex items-end justify-between"><div><p class="section-kicker">Browse categories</p><h2 class="section-title">Find what you need</h2></div><Link href="/shop" class="text-sm font-black text-prinx-600">View all →</Link></div><div class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6"><Link v-for="c in productCategories" :key="c.id" :href="`/shop/category/${c.slug}`" class="card overflow-hidden"><img :src="c.image_url" :alt="c.name" class="aspect-square w-full object-cover"><div class="p-3"><p class="font-black">{{c.name}}</p><p class="text-xs text-slate-500">{{c.products_count}} products</p></div></Link></div></section><section class="container-shell py-8"><p class="section-kicker">Popular products</p><h2 class="section-title">Featured electronics</h2><div class="mt-5 grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4"><ProductCard v-for="p in featuredProducts" :key="p.id" :product="p" compact-mobile/></div></section><section v-if="productReels?.length" class="container-shell py-8"><p class="section-kicker">Product reels</p><h2 class="section-title">See products in action</h2><div class="mt-5 flex gap-3 overflow-x-auto pb-2"><Link v-for="r in productReels" :key="r.id" :href="r.item_url" class="card w-52 shrink-0 overflow-hidden"><img :src="r.cover_url" :alt="r.title" class="aspect-[9/14] w-full object-cover"><div class="p-3"><p class="font-black">{{r.title}}</p><p class="mt-1 line-clamp-2 text-xs text-slate-500">{{r.caption}}</p></div></Link></div></section><section class="container-shell py-10"><p class="section-kicker">Technical services</p><h2 class="section-title">Professional support</h2><div class="mt-5 grid gap-3 md:grid-cols-3"><Link v-for="c in serviceCategories" :key="c.id" :href="`/services/category/${c.slug}`" class="card p-5"><p class="font-black">{{c.name}}</p><p class="mt-2 text-sm text-slate-500">{{c.description}}</p></Link></div></section></AppLayout></template>
